10	// timeChain builds a chain whose blocks carry the given per-height timestamps
11	// (nil entry means a missing timestamp).
12	func timeChain(t *testing.T, times ...*int64) *Index {
13		t.Helper()
14		index := New()
15		for i, when := range times {
16			height := int64(i + 1)
17			parent := "genesis"
18			if height > 1 {
19				parent = fmt.Sprintf("h%d", height-1)
20			}
21			block := Block{
22				Height: height,
23				Hash:   fmt.Sprintf("h%d", height),
24				Parent: parent,
25				Txs:    []string{"a"},
26				Time:   when,
27			}
28			if err := index.Append(block); err != nil {
29				t.Fatalf("setup append at %d: %v", height, err)
30			}
31		}
32		return index
33	}
34	
35	func TestQueryTxsCursorDiesOnInRangeTimestampChange(t *testing.T) {
36		t.Run("reorg changes timestamp in range", func(t *testing.T) {
37			idx := timeChain(t, intptr(10), intptr(20), intptr(30))
38			first, _ := idx.QueryTxs(TxQuery{PageSize: 1})
39			if _, err := idx.Reorg([]Block{
40				{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}, Time: intptr(999)},
41				{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a"}, Time: intptr(30)},
42			}); err != nil {
43				t.Fatal(err)
44			}
45			if _, err := idx.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor}); !errors.Is(err, ErrQueryChanged) {
46				t.Fatalf("err=%v, want ErrQueryChanged", err)
47			}
48		})
49	
50		t.Run("missing becomes known in range", func(t *testing.T) {
51			idx := timeChain(t, intptr(10), nil, intptr(30))
52			first, _ := idx.QueryTxs(TxQuery{PageSize: 1})
53			if _, err := idx.Reorg([]Block{
