		{Height: 2, Hash: "h2", Parent: "h1", Time: intptr(100)},
		{Height: 3, Hash: "h3", Parent: "h2", Time: intptr(50)},
		{Height: 4, Hash: "h4", Parent: "h3"}, // missing time among known times
		{Height: 5, Hash: "h5", Parent: "h4", Time: intptr(0)},
