22			timeBlock(2, "h2", "h1", []string{"c"}, intptr(9)),
23			timeBlock(3, "h3", "h2", []string{"a", "c"}, intptr(10)), // falls in [10,20)
24			timeBlock(4, "h4", "h3", []string{"d"}, intptr(19)),
25			timeBlock(5, "h5", "h4", []string{"a"}, intptr(20)), // excluded: end is exclusive
26			timeBlock(6, "h6", "h5", []string{"x"}, nil),        // missing time
27		}
28		for _, b := range blocks {
29			if err := index.Append(b); err != nil {
30				t.Fatal(err)
31			}
32		}
33		stats, err := index.QueryTimeStats(TimeStatsQuery{Start: 0, End: 20, StepSeconds: 10})
34		if err != nil {
35			t.Fatal(err)
36		}
37		want := TimeStats{
38			Buckets: []TimeBucket{
39				{Start: 0, End: 10, TxCount: 4, DistinctTxIDs: 3, Blocks: 2},
40				{Start: 10, End: 20, TxCount: 3, DistinctTxIDs: 3, Blocks: 2},
41			},
42			Totals:            TimeTotals{TxCount: 7, DistinctTxIDs: 4, Blocks: 4},
43			FromHeight:        1,
44			ToHeight:          6,
45			MissingTimeBlocks: 1,
46		}
47		if !reflect.DeepEqual(stats, want) {
48			t.Fatalf("stats=%+v\nwant=%+v", stats, want)
49		}
50	}
