53		index := New()
54		if err := index.Append(timeBlock(1, "h1", "g", []string{"a"}, intptr(5))); err != nil {
55			t.Fatal(err)
56		}
57		// Window [0,25) with step 10 -> three buckets, last cut to 25.
58		stats, err := index.QueryTimeStats(TimeStatsQuery{Start: 0, End: 25, StepSeconds: 10})
59		if err != nil {
60			t.Fatal(err)
61		}
62		wantBounds := [][2]int64{{0, 10}, {10, 20}, {20, 25}}
63		if len(stats.Buckets) != 3 {
64			t.Fatalf("buckets=%d, want 3", len(stats.Buckets))
65		}
66		for i, b := range stats.Buckets {
67			if b.Start != wantBounds[i][0] || b.End != wantBounds[i][1] {
68				t.Fatalf("bucket %d bounds=[%d,%d), want [%d,%d)", i, b.Start, b.End, wantBounds[i][0], wantBounds[i][1])
69			}
70		}
71		// Only the first bucket has data; the other two are zero-valued.
72		if stats.Buckets[0].TxCount != 1 || stats.Buckets[1].TxCount != 0 || stats.Buckets[2].TxCount != 0 {
73			t.Fatalf("unexpected bucket counts: %+v", stats.Buckets)
74		}
