76			t.Fatalf("empty bucket not zero: %+v", stats.Buckets[1])
77		}
78		if stats.Totals != (TimeTotals{TxCount: 1, DistinctTxIDs: 1, Blocks: 1}) {
79			t.Fatalf("totals=%+v", stats.Totals)
80		}
81	}
