83	func TestQueryTimeStatsTotalsDistinctIsGlobalNotSummed(t *testing.T) {
84		index := New()
85		blocks := []Block{
86			timeBlock(1, "h1", "g", []string{"a", "b"}, intptr(0)),
87			timeBlock(2, "h2", "h1", []string{"b", "c"}, intptr(10)),
88			timeBlock(3, "h3", "h2", []string{"a", "c"}, intptr(20)),
89		}
90		for _, b := range blocks {
91			if err := index.Append(b); err != nil {
92				t.Fatal(err)
93			}
94		}
95		stats, err := index.QueryTimeStats(TimeStatsQuery{Start: 0, End: 30, StepSeconds: 10})
96		if err != nil {
97			t.Fatal(err)
98		}
99		for i, want := range []int64{2, 2, 2} {
